"""Real Rust store, generated bytes/video only; never screen/audio capture."""
from __future__ import annotations

import json
import io
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import threading
import time
import unittest
from unittest.mock import MagicMock, patch

from murmur.recorder import RecorderError
from murmur.replay_store import DiskReplayBuffer, binary


class StoreDeadlineTests(unittest.TestCase):
    def test_unresponsive_helper_cannot_block_append_or_cleanup(self):
        # Exercise stalled response AND a full input pipe without leaving a
        # hung process behind when running against the pre-fix implementation.
        for stall_write in (False, True):
            with self.subTest(stall_write=stall_write), tempfile.TemporaryDirectory() as folder:
                release = threading.Event()
                reads = []

                class Output:
                    def readline(self, limit):
                        if not reads:
                            reads.append(True)
                            return b'{"ok":true}\n'
                        release.wait(5)
                        return b''

                    def close(self):
                        pass

                class Input(io.BytesIO):
                    def write(self, value):
                        if stall_write and reads:
                            release.wait(5)
                            raise BrokenPipeError('helper stopped')
                        return super().write(value)

                process = MagicMock(stdin=Input(), stdout=Output())
                process.kill.side_effect = release.set
                errors = []
                with patch('murmur.replay_store.binary', return_value='fake-store'), \
                        patch('murmur.replay_store.subprocess.Popen', return_value=process), \
                        patch.object(DiskReplayBuffer, 'REQUEST_TIMEOUT', .05, create=True):
                    buffer = DiskReplayBuffer(2, 1024, str(Path(folder) / 'buffer'))

                    def append():
                        try:
                            buffer.append(b'video', 0)
                        except RecorderError as error:
                            errors.append(str(error))

                    worker = threading.Thread(target=append)
                    worker.start()
                    try:
                        worker.join(timeout=1)
                        self.assertFalse(worker.is_alive(), 'A stalled helper blocked the capture thread')
                        self.assertTrue(errors)
                        self.assertIn('deadline', errors[0])
                        process.kill.assert_called()
                    finally:
                        release.set()
                        worker.join(timeout=2)
                        buffer.close()
                    self.assertFalse(buffer._watchdog.is_alive())


def available():
    try:
        binary()
        return True
    except RecorderError:
        return False


@unittest.skipUnless(available(), "build scripts/build_replay_store.py")
class DiskStoreTests(unittest.TestCase):
    def setUp(self):
        parent = (Path(tempfile.gettempdir()) / "jarvis-replay-store-tests" if os.name == "nt"
                  else Path(__file__).resolve().parents[1] / "build/replay-storage/test-tmp")
        parent.mkdir(parents=True, exist_ok=True)
        self.directory = tempfile.TemporaryDirectory(prefix="jarvis-disk-store-", dir=parent)
        self.addCleanup(self.directory.cleanup)
        self.root = Path(self.directory.name)

    def store(self, seconds=2, cap=1024, directory=None):
        buffer = DiskReplayBuffer(seconds, cap, str(directory or self.root / "buffer"))
        self.addCleanup(buffer.close)
        return buffer

    def test_capture_order_time_limit_and_private_permissions(self):
        buffer = self.store(seconds=2)
        buffer.append(b"b", 1)
        buffer.append(b"c", 2)
        buffer.append(b"a", 0)
        with buffer.files() as paths:
            self.assertEqual([p.read_bytes() for p in paths], [b"b", b"c"])
            if os.name != "nt":
                self.assertEqual(paths[0].parent.stat().st_mode & 0o777, 0o700)
                self.assertEqual(paths[0].stat().st_mode & 0o777, 0o600)
            else:
                import win32security
                from murmur.windows.system import user_sid
                sid = win32security.ConvertSidToStringSid(user_sid())
                for path in (paths[0], paths[0].parent):
                    acl = win32security.GetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION).GetSecurityDescriptorDacl()
                    self.assertGreater(acl.GetAceCount(), 0)
                    identities = [win32security.ConvertSidToStringSid(acl.GetAce(i)[2]) for i in range(acl.GetAceCount())]
                    self.assertTrue(all(identity in (sid, "S-1-5-18") for identity in identities), (str(path), identities, sid))
        buffer.close()
        self.assertEqual(list((self.root / "buffer").glob("session-*")), [])

    def test_save_during_warmup_does_not_end_the_buffer(self):
        buffer = self.store()
        with self.assertRaisesRegex(RecorderError, "warming up"):
            with buffer.files():
                self.fail("No complete segments")
        buffer.append(b"ready", 0)
        with buffer.files() as paths:
            self.assertEqual(paths[0].read_bytes(), b"ready")

    def test_byte_limit_evicts_oldest_and_counts_pending(self):
        buffer = self.store(seconds=10, cap=5)
        for sequence, data in enumerate((b"aa", b"bb", b"ccc")):
            buffer.append(data, sequence)
        with buffer.files() as paths:
            self.assertEqual([p.read_bytes() for p in paths], [b"bb", b"ccc"])
        other = self.store(cap=5, directory=self.root / "other")
        other.append(b"abc", 1)
        with self.assertRaisesRegex(RecorderError, "pending segments"):
            other.append(b"def", 2)
        self.assertLessEqual(sum(p.stat().st_size for p in (self.root / "other").rglob("*.mkv")), 5)

    def test_save_pins_files_through_rollover_and_stop(self):
        buffer = self.store(seconds=2, cap=100)
        buffer.append(b"a", 0)
        buffer.append(b"b", 1)
        with buffer.files() as saved:
            for sequence in range(2, 8):
                buffer.append(str(sequence).encode(), sequence)
            self.assertEqual([p.read_bytes() for p in saved], [b"a", b"b"])
            buffer.close()
            self.assertTrue(all(p.exists() for p in saved))
        self.assertTrue(all(not p.exists() for p in saved))

    def test_save_and_pending_files_share_cap_and_fail_safely(self):
        buffer = self.store(seconds=1, cap=4)
        buffer.append(b"old", 0)
        with buffer.files() as saved:
            # A rejected large payload must be drained, not deadlock its writer.
            with self.assertRaisesRegex(RecorderError, "budget"):
                buffer.append(b"x" * (1024 * 1024), 1)
            self.assertEqual(saved[0].read_bytes(), b"old")
        other = self.store(seconds=1, cap=4, directory=self.root / "other")
        other.append(b"old", 0)
        with other.files() as saved:
            with self.assertRaisesRegex(RecorderError, "occupied by a save"):
                other.append(b"new", 1)
            self.assertEqual(saved[0].read_bytes(), b"old")

    def test_next_start_removes_only_marked_stale_sessions(self):
        buffer = self.store()
        buffer.append(b"private", 0)
        stale = next((self.root / "buffer").glob("session-*"))
        buffer.process.kill()
        buffer.process.wait(timeout=3)
        self.assertTrue(stale.exists())
        unmarked = self.root / "buffer/session-dead"
        unmarked.mkdir(mode=0o700)
        (unmarked / "keep").write_bytes(b"unrelated")
        new = self.store()
        self.assertFalse(stale.exists())
        self.assertEqual((unmarked / "keep").read_bytes(), b"unrelated")
        new.append(b"new", 0)

    def test_an_active_root_cannot_be_cleaned_by_another_store(self):
        buffer = self.store()
        buffer.append(b"keep", 0)
        with self.assertRaisesRegex(RecorderError, "already in use"):
            self.store()
        with buffer.files() as paths:
            self.assertEqual(paths[0].read_bytes(), b"keep")

    @unittest.skipIf(os.name == "nt", "POSIX directory permissions and links")
    def test_insecure_directory_and_symlink_are_refused(self):
        root = self.root / "insecure"
        root.mkdir(mode=0o755)
        root.chmod(0o755)
        with self.assertRaisesRegex(RecorderError, "private directory"):
            self.store(directory=root)
        linked = self.root / "linked"
        linked.symlink_to(root, target_is_directory=True)
        with self.assertRaisesRegex(RecorderError, "private directory"):
            self.store(directory=linked)

    @unittest.skipUnless(os.name != "nt" and Path("/dev/shm").is_dir(), "Linux tmpfs")
    def test_tmpfs_is_refused(self):
        with tempfile.TemporaryDirectory(dir="/dev/shm", prefix="jarvis-store-") as directory:
            with self.assertRaisesRegex(RecorderError, "tmpfs"):
                self.store(directory=Path(directory) / "buffer")

    def test_sequence_errors_do_not_publish_a_segment(self):
        for sequence in (-1, 3):
            buffer = self.store(directory=self.root / f"bad-{sequence}")
            with self.assertRaises(RecorderError):
                buffer.append(b"bad", sequence)
            self.assertEqual(list((self.root / f"bad-{sequence}").rglob("*.mkv")), [])

    @unittest.skipIf(os.name == "nt", "POSIX injected filesystem write failure")
    def test_os_write_failure_removes_partial_segment_and_preserves_saved_files(self):
        import resource
        import signal
        original = subprocess.Popen

        def limited(*args, **kwargs):
            def limit():
                signal.signal(signal.SIGXFSZ, signal.SIG_IGN)
                resource.setrlimit(resource.RLIMIT_FSIZE, (128, 128))
            return original(*args, preexec_fn=limit, **kwargs)

        with patch("murmur.replay_store.subprocess.Popen", side_effect=limited):
            buffer = self.store(cap=1024)
        buffer.append(b"old", 0)
        with buffer.files() as paths:
            with self.assertRaisesRegex(RecorderError, "File too large"):
                buffer.append(b"x" * 512, 1)
            self.assertEqual(paths[0].read_bytes(), b"old")
            self.assertEqual(len(list(paths[0].parent.glob("*.mkv"))), 1)

    def test_save_waits_for_the_current_second_and_has_a_deadline(self):
        buffer = self.store()
        buffer.append(b"old", 0)
        after = time.monotonic()
        thread = threading.Thread(target=lambda: (time.sleep(.03), buffer.append(b"current", 1)))
        thread.start()
        try:
            with buffer.files(after=after, timeout=1) as paths:
                self.assertEqual(paths[-1].read_bytes(), b"current")
        finally:
            thread.join(timeout=2)
        with self.assertRaisesRegex(RecorderError, "current second"):
            with buffer.files(after=time.monotonic(), timeout=.01):
                self.fail("No new segment")

    @unittest.skipIf(os.name == "nt", "POSIX stopped-process fault injection")
    def test_stopped_real_helper_is_killed_and_next_start_cleans_its_session(self):
        import signal
        buffer = self.store()
        buffer.append(b'old', 0)
        session = next((self.root / 'buffer').glob('session-*'))
        os.kill(buffer.process.pid, signal.SIGSTOP)
        try:
            with patch.object(DiskReplayBuffer, 'REQUEST_TIMEOUT', .1):
                with self.assertRaisesRegex(RecorderError, 'deadline'):
                    buffer.append(b'new', 1)
        finally:
            buffer.close()
        self.assertIsNotNone(buffer.process.poll())
        self.assertFalse(buffer._watchdog.is_alive())
        self.assertTrue(session.exists(), 'SIGKILL leaves a marked crash session')
        replacement = self.store()
        self.assertFalse(session.exists())
        replacement.append(b'recovered', 0)

    @unittest.skipUnless(shutil.which("ffmpeg") and shutil.which("ffprobe"), "FFmpeg")
    def test_real_video_save_during_rollover_and_full_decode(self):
        fixture = self.root / "fixture.mkv"
        subprocess.run([shutil.which("ffmpeg"), "-v", "error", "-f", "lavfi", "-i", "testsrc2=size=96x64:rate=10", "-t", "1", "-c:v", "libx264", "-threads", "1", "-pix_fmt", "yuv420p", str(fixture)], check=True, timeout=15)
        data = fixture.read_bytes()
        buffer = self.store(seconds=2, cap=len(data) * 6)
        buffer.append(data, 0)
        buffer.append(data, 1)
        from murmur.windows.capture import Replay
        from murmur.config import validate
        from unittest.mock import MagicMock
        capture = Replay(validate({"replay": {"storage": "disk"}}))
        capture._buffer, capture._folder = buffer, self.root
        capture._process = MagicMock()
        original = subprocess.run

        def roll_and_run(argv, **kwargs):
            if "concat" in argv:
                for sequence in range(3, 7):
                    buffer.append(data, sequence)
            return original(argv, **kwargs)

        thread = threading.Thread(target=lambda: (time.sleep(.04), buffer.append(data, 2)))
        thread.start()
        try:
            with patch("murmur.windows.capture.subprocess.run", side_effect=roll_and_run):
                result = capture.save()
        finally:
            thread.join(timeout=2)
        path = Path(result["file"])
        self.assertTrue(path.exists())
        probe = json.loads(original([shutil.which("ffprobe"), "-v", "error", "-show_entries", "format=duration", "-of", "json", str(path)], check=True, capture_output=True, text=True).stdout)
        self.assertAlmostEqual(float(probe["format"]["duration"]), 2.0, delta=.15)
        original([shutil.which("ffmpeg"), "-v", "error", "-xerror", "-i", str(path), "-f", "null", "-"], check=True, timeout=15, stdout=subprocess.DEVNULL)

    @unittest.skipUnless(os.name == "nt" and shutil.which("ffmpeg") and shutil.which("ffprobe"), "Windows named pipes and FFmpeg")
    def test_windows_named_pipe_capture_disk_save_and_stop(self):
        from murmur import config
        from murmur.windows import capture
        ffmpeg = shutil.which("ffmpeg")
        cfg = config.validate({
            "recording": {"configured": True, "monitor": "generated", "output_dir": str(self.root), "codec": "h264", "system_audio": False, "microphone": False},
            "replay": {"storage": "disk", "buffer_dir": str(self.root / "buffer"), "seconds": 10, "game_audio": False, "microphone": False},
        })
        def validated(_):
            return dict(cfg["recording"]), {}, ffmpeg, "cpu", self.root
        def command(*_, **kwargs):
            return [ffmpeg, "-hide_banner", "-loglevel", "error", "-n", "-re", "-f", "lavfi", "-i", "testsrc2=size=96x64:rate=10", "-map", "0:v:0", "-c:v", "libx264", "-preset", "ultrafast", "-threads", "1", "-g", "10", "-bf", "0", "-force_key_frames", "expr:gte(t,n_forced*1)"], "sdr", "h264"
        replay = capture.Replay(cfg)
        try:
            with patch.object(capture._Capture, "_validated", validated), patch.object(capture.encoding, "command", command):
                replay.start()
            deadline = time.monotonic() + 8
            while replay._buffer is not None and replay._buffer.last == 0 and time.monotonic() < deadline:
                time.sleep(.05)
            result = replay.save()
            self.assertEqual(result["state"], "on", result)
            self.assertTrue(Path(result["file"]).exists())
            self.assertEqual(replay.stop()["state"], "off")
            self.assertEqual(list((self.root / "buffer").glob("session-*")), [])
        finally:
            replay.close()


if __name__ == "__main__":
    unittest.main()
